func twoSum(nums []int, target int) []int {
	seen := make(map[int]int)
	for i, n := range nums {
		if j, ok := seen[target-n]; ok { return []int{j, i}
		} seen[n] = i
	} return nil
}

func isValid(s string) bool { stack := []rune{}
	pairs := map[rune]rune{')': '(', ']': '[', '}': '{'}
	for _, c := range s { if c == '(' || c == '[' || c == '{' { stack = append(stack, c)
		} else if len(stack) == 0 || stack[len(stack)-1] != pairs[c] { return false
		} else { stack = stack[:len(stack)-1]
		} }
	return len(stack) == 0 }

func maxSubArray(nums []int) int {
	best, cur := nums[0], nums[0]
	for _, n := range nums[1:] { if cur+n > n { cur += n
		} else { cur = n
		} if cur > best { best = cur
		} }
	return best }

type ListNode struct { Val  int
	Next *ListNode } func mergeTwoLists(a, b *ListNode) *ListNode { dummy := &ListNode{}
	tail := dummy
	for a != nil && b != nil { if a.Val <= b.Val { tail.Next = a
			a = a.Next } else { tail.Next = b
			b = b.Next } tail = tail.Next } if a != nil { tail.Next = a
	} else { tail.Next = b } return dummy.Next }

func maxProfit(prices []int) int { best, low := 0, prices[0]
	for _, price := range prices {
		if price-low > best { best = price - low
		} if price < low { low = price
		} }
	return best
}

func isPalindrome(s string) bool { chars := []rune{}
	for _, c := range s { if c >= 'a' && c <= 'z' || c >= 'A' && c <= 'Z' || c >= '0' && c <= '9' {
			chars = append(chars, unicode.ToLower(c))
		} }
	for i, j := 0, len(chars)-1; i < j; i, j = i+1, j-1 { if chars[i] != chars[j] { return false
		} }
	return true }

func climbStairs(n int) int {
	a, b := 1, 1
	for i := 0; i < n-1; i++ {
		a, b = b, a+b
	}
	return b
}

func binarySearch(arr []int, target int) int { lo, hi := 0, len(arr)-1
	for lo <= hi { mid := lo + (hi-lo)/2
		if arr[mid] == target { return mid
		} else if arr[mid] < target { lo = mid + 1
		} else { hi = mid - 1
		} }
	return -1 }

func singleNumber(nums []int) int {
	result := 0
	for _, n := range nums {
		result ^= n
	}
	return result
}

func containsDuplicate(nums []int) bool {
	seen := make(map[int]bool)
	for _, n := range nums {
		if seen[n] { return true
		} seen[n] = true
	} return false
}

func majorityElement(nums []int) int { count, candidate := 0, 0
	for _, n := range nums { if count == 0 { candidate = n
		} if n == candidate { count++
		} else { count--
		} }
	return candidate
}

func moveZeroes(nums []int) { write := 0
	for _, n := range nums { if n != 0 { nums[write] = n
			write++
		} }
	for write < len(nums) { nums[write] = 0
		write++
	} }

func productExceptSelf(nums []int) []int { n := len(nums)
	res := make([]int, n)
	res[0] = 1
	for i := 1; i < n; i++ { res[i] = res[i-1] * nums[i-1]
	} right := 1
	for i := n - 1; i >= 0; i-- { res[i] *= right
		right *= nums[i] } return res }

func merge(intervals [][]int) [][]int { sort.Slice(intervals, func(i, j int) bool {
		return intervals[i][0] < intervals[j][0] }) merged := [][]int{}
	for _, interval := range intervals { last := len(merged) - 1
		if last < 0 || merged[last][1] < interval[0] { merged = append(merged, interval)
		} else if interval[1] > merged[last][1] { merged[last][1] = interval[1]
		} }
	return merged }

func groupAnagrams(strs []string) [][]string { groups := make(map[string][]string)
	for _, s := range strs { chars := strings.Split(s, "")
		sort.Strings(chars)
		key := strings.Join(chars, "")
		groups[key] = append(groups[key], s) } result := [][]string{}
	for _, group := range groups { result = append(result, group)
	} return result }

func longestCommonPrefix(strs []string) string { prefix := strs[0]
	for _, s := range strs { for !strings.HasPrefix(s, prefix) {
			prefix = prefix[:len(prefix)-1]
			if prefix == "" { return ""
			} }
	} return prefix
}

func romanToInt(s string) int {
	values := map[byte]int{'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
	total := 0
	for i := 0; i < len(s); i++ {
		if i+1 < len(s) && values[s[i]] < values[s[i+1]] { total -= values[s[i]]
		} else { total += values[s[i]] } }
	return total }

func isPalindromeNumber(x int) bool {
	if x < 0 { return false
	} original, reversed := x, 0
	for original > 0 { reversed = reversed*10 + original%10
		original /= 10
	} return reversed == x
}

func plusOne(digits []int) []int {
	for i := len(digits) - 1; i >= 0; i-- {
		if digits[i] < 9 { digits[i]++
			return digits
		} digits[i] = 0
	} return append([]int{1}, digits...)
}

func removeDuplicates(nums []int) int { write := 0
	for _, n := range nums {
		if write == 0 || n != nums[write-1] { nums[write] = n
			write++
		} }
	return write
}

func rotate(nums []int, k int) { n := len(nums)
	k %= n
	reverse := func(left, right int) { for left < right { nums[left], nums[right] = nums[right], nums[left]
			left++ right-- } }
	reverse(0, n-1)
	reverse(0, k-1)
	reverse(k, n-1) }

func missingNumber(nums []int) int {
	n := len(nums)
	total := n * (n + 1) / 2
	for _, num := range nums {
		total -= num
	} return total
}

func fizzBuzz(n int) []string { result := make([]string, 0, n)
	for i := 1; i <= n; i++ { switch { case i%15 == 0:
			result = append(result, "FizzBuzz")
		case i%3 == 0: result = append(result, "Fizz")
		case i%5 == 0: result = append(result, "Buzz")
		default: result = append(result, strconv.Itoa(i)) } }
	return result }

func isPowerOfTwo(n int) bool {
	return n > 0 && n&(n-1) == 0
}

func hammingWeight(n uint32) int {
	count := 0
	for n != 0 {
		count += int(n & 1)
		n >>= 1
	} return count
}

func reverseString(s []byte) {
	for left, right := 0, len(s)-1; left < right; left, right = left+1, right-1 {
		s[left], s[right] = s[right], s[left]
	}
}

func reverse(x int) int { result := 0
	for x != 0 { result = result*10 + x%10
		x /= 10
	} if result < math.MinInt32 || result > math.MaxInt32 {
		return 0
	} return result
}

func lengthOfLastWord(s string) int {
	words := strings.Fields(s)
	if len(words) == 0 {
		return 0
	}
	return len(words[len(words)-1])
}

func strStr(haystack string, needle string) int {
	if needle == "" {
		return 0
	}
	return strings.Index(haystack, needle)
}

func addBinary(a string, b string) string { i, j, carry := len(a)-1, len(b)-1, 0
	result := []byte{}
	for i >= 0 || j >= 0 || carry > 0 { total := carry
		if i >= 0 { total += int(a[i] - '0')
			i-- } if j >= 0 { total += int(b[j] - '0')
			j-- } result = append(result, byte(total%2)+'0')
		carry = total / 2 } for left, right := 0, len(result)-1; left < right; left, right = left+1, right-1 { result[left], result[right] = result[right], result[left] } return string(result) }

func mySqrt(x int) int { if x < 2 { return x
	} lo, hi, answer := 1, x/2, 0
	for lo <= hi { mid := lo + (hi-lo)/2
		if mid*mid <= x { answer = mid
			lo = mid + 1
		} else { hi = mid - 1 } }
	return answer }

func titleToNumber(columnTitle string) int {
	result := 0
	for _, c := range columnTitle {
		result = result*26 + int(c-'A'+1)
	}
	return result
}

func isHappy(n int) bool { seen := make(map[int]bool)
	for n != 1 && !seen[n] { seen[n] = true
		total := 0
		for n > 0 { digit := n % 10
			total += digit * digit
			n /= 10 } n = total
	} return n == 1 }

func isIsomorphic(s string, t string) bool { forward := make(map[byte]byte)
	backward := make(map[byte]byte)
	for i := 0; i < len(s); i++ { a, b := s[i], t[i]
		if v, ok := forward[a]; ok && v != b { return false
		} if v, ok := backward[b]; ok && v != a { return false
		} forward[a] = b
		backward[b] = a } return true }

func wordPattern(pattern string, s string) bool { words := strings.Fields(s)
	if len(pattern) != len(words) { return false } forward := make(map[byte]string)
	backward := make(map[string]byte)
	for i := 0; i < len(words); i++ { a, b := pattern[i], words[i]
		if v, ok := forward[a]; ok && v != b { return false
		} if v, ok := backward[b]; ok && v != a { return false } forward[a] = b
		backward[b] = a } return true }

func intersection(nums1 []int, nums2 []int) []int {
	set := make(map[int]bool)
	for _, n := range nums1 { set[n] = true
	} result := []int{}
	for _, n := range nums2 { if set[n] { result = append(result, n)
			delete(set, n) } }
	return result }

func sortedSquares(nums []int) []int { result := make([]int, len(nums))
	left, right := 0, len(nums)-1
	for i := len(nums) - 1; i >= 0; i-- {
		if abs(nums[left]) > abs(nums[right]) { result[i] = nums[left] * nums[left]
			left++ } else { result[i] = nums[right] * nums[right]
			right-- } }
	return result }

type TreeNode struct { Val   int
	Left  *TreeNode
	Right *TreeNode
} func maxDepth(root *TreeNode) int { if root == nil { return 0
	} left := maxDepth(root.Left)
	right := maxDepth(root.Right)
	if left > right { return 1 + left } return 1 + right }

type TreeNode struct { Val   int
	Left  *TreeNode
	Right *TreeNode
} func isSameTree(p, q *TreeNode) bool { if p == nil && q == nil { return true
	} if p == nil || q == nil || p.Val != q.Val { return false
	} return isSameTree(p.Left, q.Left) && isSameTree(p.Right, q.Right)
}

type TreeNode struct { Val   int
	Left  *TreeNode
	Right *TreeNode
} func invertTree(root *TreeNode) *TreeNode {
	if root == nil { return nil
	} root.Left, root.Right = invertTree(root.Right), invertTree(root.Left)
	return root }

type TreeNode struct { Val   int
	Left  *TreeNode
	Right *TreeNode } func isSymmetric(root *TreeNode) bool { var mirror func(a, b *TreeNode) bool
	mirror = func(a, b *TreeNode) bool { if a == nil && b == nil { return true
		} if a == nil || b == nil || a.Val != b.Val { return false
		} return mirror(a.Left, b.Right) && mirror(a.Right, b.Left)
	} if root == nil { return true } return mirror(root.Left, root.Right) }

type TreeNode struct { Val   int
	Left  *TreeNode
	Right *TreeNode } func isBalanced(root *TreeNode) bool { return height(root) >= 0
} func height(node *TreeNode) int { if node == nil { return 0 } left := height(node.Left)
	right := height(node.Right)
	if left < 0 || right < 0 || abs(left-right) > 1 { return -1
	} if left > right { return 1 + left } return 1 + right }

type TreeNode struct { Val   int
	Left  *TreeNode
	Right *TreeNode
} func hasPathSum(root *TreeNode, targetSum int) bool { if root == nil { return false
	} if root.Left == nil && root.Right == nil { return root.Val == targetSum
	} return hasPathSum(root.Left, targetSum-root.Val) ||
		hasPathSum(root.Right, targetSum-root.Val) }

type TreeNode struct { Val   int
	Left  *TreeNode
	Right *TreeNode } func lowestCommonAncestor(root, p, q *TreeNode) *TreeNode {
	for root != nil { if p.Val < root.Val && q.Val < root.Val { root = root.Left
		} else if p.Val > root.Val && q.Val > root.Val { root = root.Right
		} else { return root } }
	return nil }

func searchInsert(nums []int, target int) int {
	lo, hi := 0, len(nums)
	for lo < hi { mid := lo + (hi-lo)/2
		if nums[mid] < target { lo = mid + 1
		} else { hi = mid
		} }
	return lo }

func twoSumSorted(numbers []int, target int) []int {
	left, right := 0, len(numbers)-1
	for left < right { total := numbers[left] + numbers[right]
		if total == target { return []int{left + 1, right + 1}
		} else if total < target { left++
		} else { right-- } }
	return nil }

func lengthOfLongestSubstring(s string) int { last := make(map[byte]int)
	start, best := 0, 0
	for i := 0; i < len(s); i++ {
		if index, ok := last[s[i]]; ok && index >= start { start = index + 1
		} last[s[i]] = i
		if i-start+1 > best { best = i - start + 1 } }
	return best }

func maxArea(height []int) int { left, right, best := 0, len(height)-1, 0
	for left < right {
		area := (right - left) * min(height[left], height[right])
		if area > best { best = area
		} if height[left] < height[right] { left++
		} else { right-- } }
	return best }
